static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__GNUC__)
  DATA_TYPE (* __restrict__ tmp_r)[NJ] = tmp;
  DATA_TYPE (* __restrict__ A_r)[NK] = A;
  DATA_TYPE (* __restrict__ B_r)[NJ] = B;
  DATA_TYPE (* __restrict__ C_r)[NL] = C;
  DATA_TYPE (* __restrict__ D_r)[NL] = D;
#else
  DATA_TYPE (*tmp_r)[NJ] = tmp;
  DATA_TYPE (*A_r)[NK] = A;
  DATA_TYPE (*B_r)[NJ] = B;
  DATA_TYPE (*C_r)[NL] = C;
  DATA_TYPE (*D_r)[NL] = D;
#endif

  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * __restrict__ tmp_i = tmp_r[i];
    DATA_TYPE * __restrict__ D_i = D_r[i];

    for (j = 0; j < _PB_NJ; ++j)
      tmp_i[j] = SCALAR_VAL(0.0);

    for (k = 0; k < _PB_NK; ++k) {
      DATA_TYPE aik_alpha = alpha * A_r[i][k];
      DATA_TYPE * __restrict__ B_k = B_r[k];
      j = 0;

#if defined(__GNUC__)
#pragma GCC ivdep
#endif
      for (; j + 3 < _PB_NJ; j += 4) {
        tmp_i[j]     += aik_alpha * B_k[j];
        tmp_i[j + 1] += aik_alpha * B_k[j + 1];
        tmp_i[j + 2] += aik_alpha * B_k[j + 2];
        tmp_i[j + 3] += aik_alpha * B_k[j + 3];
      }
      for (; j < _PB_NJ; ++j)
        tmp_i[j] += aik_alpha * B_k[j];
    }

    for (j = 0; j < _PB_NL; ++j)
      D_i[j] *= beta;

    for (k = 0; k < _PB_NJ; ++k) {
      DATA_TYPE tmpik = tmp_i[k];
      DATA_TYPE * __restrict__ C_k = C_r[k];
      j = 0;

#if defined(__GNUC__)
#pragma GCC ivdep
#endif
      for (; j + 3 < _PB_NL; j += 4) {
        D_i[j]     += tmpik * C_k[j];
        D_i[j + 1] += tmpik * C_k[j + 1];
        D_i[j + 2] += tmpik * C_k[j + 2];
        D_i[j + 3] += tmpik * C_k[j + 3];
      }
      for (; j < _PB_NL; ++j)
        D_i[j] += tmpik * C_k[j];
    }
  }

#pragma endscop

}

static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__GNUC__) || defined(__clang__)
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * __restrict__ Ei = &E[i][0];
    DATA_TYPE * __restrict__ Ai = &A[i][0];

    for (j = 0; j < _PB_NJ; ++j)
      Ei[j] = SCALAR_VAL(0.0);

    for (k = 0; k < _PB_NK; ++k) {
      const DATA_TYPE a_ik = Ai[k];
      DATA_TYPE * __restrict__ Bk = &B[k][0];

#if defined(__riscv)
#pragma GCC ivdep
#pragma GCC unroll 8
#endif
      for (j = 0; j < _PB_NJ; ++j)
        Ei[j] += a_ik * Bk[j];
    }
  }

  for (i = 0; i < _PB_NJ; i++) {
    DATA_TYPE * __restrict__ Fi = &F[i][0];
    DATA_TYPE * __restrict__ Ci = &C[i][0];

    for (j = 0; j < _PB_NL; ++j)
      Fi[j] = SCALAR_VAL(0.0);

    for (k = 0; k < _PB_NM; ++k) {
      const DATA_TYPE c_ik = Ci[k];
      DATA_TYPE * __restrict__ Dk = &D[k][0];

#if defined(__riscv)
#pragma GCC ivdep
#pragma GCC unroll 8
#endif
      for (j = 0; j < _PB_NL; ++j)
        Fi[j] += c_ik * Dk[j];
    }
  }

  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * __restrict__ Gi = &G[i][0];
    DATA_TYPE * __restrict__ Ei = &E[i][0];

    for (j = 0; j < _PB_NL; ++j)
      Gi[j] = SCALAR_VAL(0.0);

    for (k = 0; k < _PB_NJ; ++k) {
      const DATA_TYPE e_ik = Ei[k];
      DATA_TYPE * __restrict__ Fk = &F[k][0];

#if defined(__riscv)
#pragma GCC ivdep
#pragma GCC unroll 8
#endif
      for (j = 0; j < _PB_NL; ++j)
        Gi[j] += e_ik * Fk[j];
    }
  }
#else
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
        E[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_NK; ++k)
          E[i][j] += A[i][k] * B[k][j];
      }

  for (i = 0; i < _PB_NJ; i++)
    for (j = 0; j < _PB_NL; j++)
      {
        F[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_NM; ++k)
          F[i][j] += C[i][k] * D[k][j];
      }

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
        G[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_NJ; ++k)
          G[i][j] += E[i][k] * F[k][j];
      }
#endif

#pragma endscop

}

static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0)+mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0)+mul2;
  f = d;

  {
    const int n1 = _PB_N - 1;
    const DATA_TYPE one = SCALAR_VAL(1.0);
    const DATA_TYPE zero = SCALAR_VAL(0.0);
    const DATA_TYPE two = SCALAR_VAL(2.0);
    const DATA_TYPE one_plus_2d = one + two * d;
    const DATA_TYPE one_plus_2a = one + two * a;

    for (t = 1; t <= _PB_TSTEPS; t++) {

      for (i = 1; i < n1; i++) {
        DATA_TYPE *restrict pi = &p[i][0];
        DATA_TYPE *restrict qi = &q[i][0];

        v[0][i] = one;
        pi[0] = zero;
        qi[0] = v[0][i];

        {
          DATA_TYPE prev_p = zero;
          DATA_TYPE prev_q = one;

          for (j = 1; j < n1; j++) {
            DATA_TYPE uj_im1 = u[j][i-1];
            DATA_TYPE uj_i   = u[j][i];
            DATA_TYPE uj_ip1 = u[j][i+1];
            DATA_TYPE denom  = a * prev_p + b;
            DATA_TYPE invd   = one / denom;
            DATA_TYPE pj     = -c * invd;
            DATA_TYPE qj     = (-d * uj_im1 + one_plus_2d * uj_i - f * uj_ip1 - a * prev_q) * invd;

            pi[j] = pj;
            qi[j] = qj;
            prev_p = pj;
            prev_q = qj;
          }
        }

        v[_PB_N-1][i] = one;
        for (j = _PB_N - 2; j >= 1; --j) {
          v[j][i] = pi[j] * v[j+1][i] + qi[j];
        }
      }

      for (i = 1; i < n1; i++) {
        DATA_TYPE *restrict ui   = &u[i][0];
        DATA_TYPE *restrict pi   = &p[i][0];
        DATA_TYPE *restrict qi   = &q[i][0];
        DATA_TYPE *restrict vim1 = &v[i-1][0];
        DATA_TYPE *restrict vi   = &v[i][0];
        DATA_TYPE *restrict vip1 = &v[i+1][0];

        ui[0] = one;
        pi[0] = zero;
        qi[0] = ui[0];

        {
          DATA_TYPE prev_p = zero;
          DATA_TYPE prev_q = one;

          for (j = 1; j < n1; j++) {
            DATA_TYPE vm1j = vim1[j];
            DATA_TYPE v0j  = vi[j];
            DATA_TYPE vp1j = vip1[j];
            DATA_TYPE denom = d * prev_p + e;
            DATA_TYPE invd  = one / denom;
            DATA_TYPE pj    = -f * invd;
            DATA_TYPE qj    = (-a * vm1j + one_plus_2a * v0j - c * vp1j - d * prev_q) * invd;

            pi[j] = pj;
            qi[j] = qj;
            prev_p = pj;
            prev_q = qj;
          }
        }

        ui[_PB_N-1] = one;
        for (j = _PB_N - 2; j >= 1; --j) {
          ui[j] = pi[j] * ui[j+1] + qi[j];
        }
      }
    }
  }

#pragma endscop
}

static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
#    if defined(DATA_TYPE_IS_DOUBLE)
      for (i = 0; i < _PB_N; ++i)
        y[i] = 0;

      for (i = 0; i < _PB_M; ++i)
      {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        int avl = _PB_N;
        int idx = 0;

        while (avl > 0)
        {
          size_t vl = __riscv_vsetvl_e64m1(avl);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][idx], vl);
          vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[idx], vl);
          vfloat64m1_t vmul = __riscv_vfmul_vv_f64m1(va, vx, vl);
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), vl);
          vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vmul, vzero, vl);
          sum += __riscv_vfmv_f_s_f64m1_f64(vred);
          idx += (int)vl;
          avl -= (int)vl;
        }

        tmp[i] = sum;

        avl = _PB_N;
        idx = 0;
        while (avl > 0)
        {
          size_t vl = __riscv_vsetvl_e64m1(avl);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][idx], vl);
          vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[idx], vl);
          vy = __riscv_vfmacc_vf_f64m1(vy, sum, va, vl);
          __riscv_vse64_v_f64m1(&y[idx], vy, vl);
          idx += (int)vl;
          avl -= (int)vl;
        }
      }
#    elif defined(DATA_TYPE_IS_FLOAT)
      for (i = 0; i < _PB_N; ++i)
        y[i] = 0;

      for (i = 0; i < _PB_M; ++i)
      {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        int avl = _PB_N;
        int idx = 0;

        while (avl > 0)
        {
          size_t vl = __riscv_vsetvl_e32m1(avl);
          vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][idx], vl);
          vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[idx], vl);
          vfloat32m1_t vmul = __riscv_vfmul_vv_f32m1(va, vx, vl);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(SCALAR_VAL(0.0), vl);
          vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vmul, vzero, vl);
          sum += __riscv_vfmv_f_s_f32m1_f32(vred);
          idx += (int)vl;
          avl -= (int)vl;
        }

        tmp[i] = sum;

        avl = _PB_N;
        idx = 0;
        while (avl > 0)
        {
          size_t vl = __riscv_vsetvl_e32m1(avl);
          vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][idx], vl);
          vfloat32m1_t vy = __riscv_vle32_v_f32m1(&y[idx], vl);
          vy = __riscv_vfmacc_vf_f32m1(vy, sum, va, vl);
          __riscv_vse32_v_f32m1(&y[idx], vy, vl);
          idx += (int)vl;
          avl -= (int)vl;
        }
      }
#    else
      for (i = 0; i < _PB_N; i++)
        y[i] = 0;
      for (i = 0; i < _PB_M; i++)
      {
        tmp[i] = SCALAR_VAL(0.0);
        for (j = 0; j < _PB_N; j++)
          tmp[i] = tmp[i] + A[i][j] * x[j];
        for (j = 0; j < _PB_N; j++)
          y[j] = y[j] + A[i][j] * tmp[i];
      }
#    endif
#  else
    for (i = 0; i < _PB_N; i++)
      y[i] = 0;
    for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      DATA_TYPE *Ai = &A[i][0];
      for (j = 0; j < _PB_N; j++)
        sum = sum + Ai[j] * x[j];
      tmp[i] = sum;
      for (j = 0; j < _PB_N; j++)
        y[j] = y[j] + Ai[j] * sum;
    }
#  endif
#else
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    DATA_TYPE *Ai = &A[i][0];
    for (j = 0; j < _PB_N; j++)
      sum = sum + Ai[j] * x[j];
    tmp[i] = sum;
    for (j = 0; j < _PB_N; j++)
      y[j] = y[j] + Ai[j] * sum;
  }
#endif
#pragma endscop

}

static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

#if defined(__riscv_vector)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE qi = SCALAR_VAL(0.0);
      DATA_TYPE ri = r[i];
      DATA_TYPE *Ai = &A[i][0];

#if defined(DATA_TYPE_IS_DOUBLE)
      {
        size_t rem = (size_t)_PB_M;
        j = 0;
        while (rem > 0)
          {
            size_t vl = __riscv_vsetvl_e64m1(rem);
            vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)(Ai + j), vl);
            vfloat64m1_t vs = __riscv_vle64_v_f64m1((const double *)(s + j), vl);
            vfloat64m1_t vp = __riscv_vle64_v_f64m1((const double *)(p + j), vl);

            vs = __riscv_vfmacc_vf_f64m1(vs, (double)ri, va, vl);
            __riscv_vse64_v_f64m1((double *)(s + j), vs, vl);

            {
              vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(va, vp, vl);
              vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
              vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vzero, vprod, vl);
              qi += __riscv_vfmv_f_s_f64m1_f64(vred);
            }

            j += (int)vl;
            rem -= vl;
          }
      }
#elif defined(DATA_TYPE_IS_FLOAT)
      {
        size_t rem = (size_t)_PB_M;
        j = 0;
        while (rem > 0)
          {
            size_t vl = __riscv_vsetvl_e32m1(rem);
            vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)(Ai + j), vl);
            vfloat32m1_t vs = __riscv_vle32_v_f32m1((const float *)(s + j), vl);
            vfloat32m1_t vp = __riscv_vle32_v_f32m1((const float *)(p + j), vl);

            vs = __riscv_vfmacc_vf_f32m1(vs, (float)ri, va, vl);
            __riscv_vse32_v_f32m1((float *)(s + j), vs, vl);

            {
              vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(va, vp, vl);
              vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
              vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vzero, vprod, vl);
              qi += __riscv_vfmv_f_s_f32m1_f32(vred);
            }

            j += (int)vl;
            rem -= vl;
          }
      }
#else
      for (j = 0; j < _PB_M; j++)
        {
          s[j] = s[j] + r[i] * A[i][j];
          qi = qi + A[i][j] * p[j];
        }
#endif

      q[i] = qi;
    }
#else
  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r[i] * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
#endif
#pragma endscop

}

static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

    for (j = 0; j < i; j++) {
      DATA_TYPE sum = A[i][j];
      DATA_TYPE *Ai = &A[i][0];
      DATA_TYPE *Aj = &A[j][0];

      /* Keep the computation structure amenable to RVV auto-vectorization. */
      for (k = 0; k + 3 < j; k += 4) {
        sum -= Ai[k] * Aj[k];
        sum -= Ai[k + 1] * Aj[k + 1];
        sum -= Ai[k + 2] * Aj[k + 2];
        sum -= Ai[k + 3] * Aj[k + 3];
      }
      for (; k < j; k++) {
        sum -= Ai[k] * Aj[k];
      }

      A[i][j] = sum / A[j][j];
    }

    {
      DATA_TYPE sum = A[i][i];
      DATA_TYPE *Ai = &A[i][0];

      /* Keep the computation structure amenable to RVV auto-vectorization. */
      for (k = 0; k + 3 < i; k += 4) {
        sum -= Ai[k] * Ai[k];
        sum -= Ai[k + 1] * Ai[k + 1];
        sum -= Ai[k + 2] * Ai[k + 2];
        sum -= Ai[k + 3] * Ai[k + 3];
      }
      for (; k < i; k++) {
        sum -= Ai[k] * Ai[k];
      }

      A[i][i] = SQRT_FUN(sum);
    }
  }
#pragma endscop

}

static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);
  DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        sum += data[i][j];
      mean[j] = sum / float_n;
    }

  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE m_j = mean[j];
      DATA_TYPE sumsq = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        {
          DATA_TYPE d = data[i][j] - m_j;
          sumsq += d * d;
        }
      sumsq /= float_n;
      sumsq = SQRT_FUN(sumsq);
      stddev[j] = sumsq <= eps ? SCALAR_VAL(1.0) : sumsq;
    }

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *data_i = data[i];
      int jj = 0;

      for (; jj + 3 < _PB_M; jj += 4)
        {
          DATA_TYPE v0 = data_i[jj]     - mean[jj];
          DATA_TYPE v1 = data_i[jj + 1] - mean[jj + 1];
          DATA_TYPE v2 = data_i[jj + 2] - mean[jj + 2];
          DATA_TYPE v3 = data_i[jj + 3] - mean[jj + 3];

          data_i[jj]     = v0 / (sqrt_float_n * stddev[jj]);
          data_i[jj + 1] = v1 / (sqrt_float_n * stddev[jj + 1]);
          data_i[jj + 2] = v2 / (sqrt_float_n * stddev[jj + 2]);
          data_i[jj + 3] = v3 / (sqrt_float_n * stddev[jj + 3]);
        }

      for (; jj < _PB_M; j++)
        {
          data_i[jj] -= mean[jj];
          data_i[jj] /= sqrt_float_n * stddev[jj];
        }
    }

  for (i = 0; i < _PB_M - 1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);

      for (j = i + 1; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);
          int kk = 0;

          for (; kk + 3 < _PB_N; kk += 4)
            {
              sum += data[kk][i]     * data[kk][j];
              sum += data[kk + 1][i] * data[kk + 1][j];
              sum += data[kk + 2][i] * data[kk + 2][j];
              sum += data[kk + 3][i] * data[kk + 3][j];
            }

          for (; kk < _PB_N; kk++)
            sum += data[kk][i] * data[kk][j];

          corr[i][j] = sum;
          corr[j][i] = sum;
        }
    }

  corr[_PB_M - 1][_PB_M - 1] = SCALAR_VAL(1.0);
#pragma endscop

}

static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector) && defined(__has_include)
# if __has_include(<riscv_vector.h>)
#  include <riscv_vector.h>

  /* Mean of columns */
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        sum += data[i][j];
      mean[j] = sum / float_n;
    }

  /* Center data rows with RVV */
  for (i = 0; i < _PB_N; i++)
    {
      int jj = 0;
      while (jj < _PB_M)
        {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - jj));
          vfloat64m1_t vdata = __riscv_vle64_v_f64m1(&data[i][jj], vl);
          vfloat64m1_t vmean = __riscv_vle64_v_f64m1(&mean[jj], vl);
          vdata = __riscv_vfsub_vv_f64m1(vdata, vmean, vl);
          __riscv_vse64_v_f64m1(&data[i][jj], vdata, vl);
          jj += (int)vl;
        }
    }

  /* Covariance matrix */
  {
    const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);
    const ptrdiff_t stride = (ptrdiff_t)(_PB_M * (int)sizeof(DATA_TYPE));

    for (i = 0; i < _PB_M; i++)
      {
        cov[i][i] = SCALAR_VAL(0.0);

        for (j = i; j < _PB_M; j++)
          {
            DATA_TYPE sum = SCALAR_VAL(0.0);
            int kk = 0;

            while (kk < _PB_N)
              {
                size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - kk));
                vfloat64m1_t vi = __riscv_vlse64_v_f64m1(&data[kk][i], stride, vl);
                vfloat64m1_t vj = __riscv_vlse64_v_f64m1(&data[kk][j], stride, vl);
                vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), vl);
                vacc = __riscv_vfmacc_vv_f64m1(vacc, vi, vj, vl);
                sum += __riscv_vfredusum_vs_f64m1_f64m1(
                         vacc,
                         __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.0), 1),
                         vl);
                kk += (int)vl;
              }

            cov[i][j] = sum / denom;
            cov[j][i] = cov[i][j];
          }
      }
  }

# else

  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        cov[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
	  cov[i][j] += data[k][i] * data[k][j];
        cov[i][j] /= (float_n - SCALAR_VAL(1.0));
        cov[j][i] = cov[i][j];
      }

# endif
#else

  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        cov[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
	  cov[i][j] += data[k][i] * data[k][j];
        cov[i][j] /= (float_n - SCALAR_VAL(1.0));
        cov[j][i] = cov[i][j];
      }

#endif
#pragma endscop

}

static
void kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i, j;
    DATA_TYPE xm1, tm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE tp1, tp2;
    DATA_TYPE yp1, yp2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    {
        const DATA_TYPE exp_alpha = EXP_FUN(-alpha);
        const DATA_TYPE exp_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);
        k = (SCALAR_VAL(1.0) - exp_alpha) * (SCALAR_VAL(1.0) - exp_alpha) /
            (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * exp_alpha - EXP_FUN(SCALAR_VAL(2.0) * alpha));
        a1 = a5 = k;
        a2 = a6 = k * exp_alpha * (alpha - SCALAR_VAL(1.0));
        a3 = a7 = k * exp_alpha * (alpha + SCALAR_VAL(1.0));
        a4 = a8 = -k * exp_2alpha;
        b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
        b2 = -exp_2alpha;
        c1 = c2 = 1;
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE * restrict imgIn_i = &imgIn[i][0];
        DATA_TYPE * restrict y1_i = &y1[i][0];
        xm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        for (j = 0; j < _PB_H; j++) {
            const DATA_TYPE x0 = imgIn_i[j];
            const DATA_TYPE y0 = a1 * x0 + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_i[j] = y0;
            xm1 = x0;
            ym2 = ym1;
            ym1 = y0;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE * restrict imgIn_i = &imgIn[i][0];
        DATA_TYPE * restrict y2_i = &y2[i][0];
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);

        for (j = _PB_H - 1; j >= 0; j--) {
            const DATA_TYPE yv = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_i[j] = yv;
            xp2 = xp1;
            xp1 = imgIn_i[j];
            yp2 = yp1;
            yp1 = yv;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE * restrict y1_i = &y1[i][0];
        DATA_TYPE * restrict y2_i = &y2[i][0];
        DATA_TYPE * restrict out_i = &imgOut[i][0];

        for (j = 0; j < _PB_H; j++) {
            out_i[j] = c1 * (y1_i[j] + y2_i[j]);
        }
    }

    for (j = 0; j < _PB_H; j++) {
        tm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        for (i = 0; i < _PB_W; i++) {
            const DATA_TYPE x0 = imgOut[i][j];
            const DATA_TYPE y0 = a5 * x0 + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1[i][j] = y0;
            tm1 = x0;
            ym2 = ym1;
            ym1 = y0;
        }
    }

    for (j = 0; j < _PB_H; j++) {
        tp1 = SCALAR_VAL(0.0);
        tp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);

        for (i = _PB_W - 1; i >= 0; i--) {
            const DATA_TYPE yv = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2[i][j] = yv;
            tp2 = tp1;
            tp1 = imgOut[i][j];
            yp2 = yp1;
            yp1 = yv;
        }
    }

    for (i = 0; i < _PB_W; i++) {
        DATA_TYPE * restrict y1_i = &y1[i][0];
        DATA_TYPE * restrict y2_i = &y2[i][0];
        DATA_TYPE * restrict out_i = &imgOut[i][0];

        for (j = 0; j < _PB_H; j++) {
            out_i[j] = c2 * (y1_i[j] + y2_i[j]);
        }
    }

#pragma endscop
}

void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      DATA_TYPE *a_rq = &A[r][q][0];

      for (p = 0; p < _PB_NP; p++)
        sum[p] = SCALAR_VAL(0.0);

      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_scalar = a_rq[s];
        DATA_TYPE *c4_row = &C4[s][0];

        p = 0;
#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
        for (; p + 7 < _PB_NP; p += 8) {
          sum[p + 0] += a_scalar * c4_row[p + 0];
          sum[p + 1] += a_scalar * c4_row[p + 1];
          sum[p + 2] += a_scalar * c4_row[p + 2];
          sum[p + 3] += a_scalar * c4_row[p + 3];
          sum[p + 4] += a_scalar * c4_row[p + 4];
          sum[p + 5] += a_scalar * c4_row[p + 5];
          sum[p + 6] += a_scalar * c4_row[p + 6];
          sum[p + 7] += a_scalar * c4_row[p + 7];
        }
        for (; p < _PB_NP; p++)
          sum[p] += a_scalar * c4_row[p];
      }

      for (p = 0; p < _PB_NP; p++)
        a_rq[p] = sum[p];
    }
  }
#pragma endscop
}

static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE z[N];
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;
    sum = SCALAR_VAL(0.0);

    {
      const DATA_TYPE *pr = r + k - 1;
      const DATA_TYPE *py = y;
      int rem = k;

#if defined(__GNUC__)
#pragma GCC unroll 8
#endif
      for (i = 0; i + 3 < rem; i += 4) {
        sum += pr[-i] * py[i]
             + pr[-(i + 1)] * py[i + 1]
             + pr[-(i + 2)] * py[i + 2]
             + pr[-(i + 3)] * py[i + 3];
      }
      for (; i < rem; i++) {
        sum += pr[-i] * py[i];
      }
    }

    alpha = -(r[k] + sum) / beta;

    {
      DATA_TYPE *pz = z;
      DATA_TYPE *pyf = y;
      const DATA_TYPE *pyr = y + k - 1;
      int rem = k;

#if defined(__GNUC__)
#pragma GCC unroll 8
#endif
      for (i = 0; i + 3 < rem; i += 4) {
        pz[i]     = pyf[i]     + alpha * pyr[-i];
        pz[i + 1] = pyf[i + 1] + alpha * pyr[-(i + 1)];
        pz[i + 2] = pyf[i + 2] + alpha * pyr[-(i + 2)];
        pz[i + 3] = pyf[i + 3] + alpha * pyr[-(i + 3)];
      }
      for (; i < rem; i++) {
        pz[i] = pyf[i] + alpha * pyr[-i];
      }
    }

    {
      DATA_TYPE *pyw = y;
      const DATA_TYPE *pzr = z;
      int rem = k;

#if defined(__GNUC__)
#pragma GCC ivdep
#pragma GCC unroll 8
#endif
      for (i = 0; i + 7 < rem; i += 8) {
        pyw[i]     = pzr[i];
        pyw[i + 1] = pzr[i + 1];
        pyw[i + 2] = pzr[i + 2];
        pyw[i + 3] = pzr[i + 3];
        pyw[i + 4] = pzr[i + 4];
        pyw[i + 5] = pzr[i + 5];
        pyw[i + 6] = pzr[i + 6];
        pyw[i + 7] = pzr[i + 7];
      }
      for (; i < rem; i++) {
        pyw[i] = pzr[i];
      }
    }

    y[k] = alpha;
  }
#pragma endscop
}

static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  {
    const DATA_TYPE c05 = SCALAR_VAL(0.5);
    const DATA_TYPE c07 = SCALAR_VAL(0.7);

    for (t = 0; t < _PB_TMAX; t++)
    {
      DATA_TYPE *restrict ey0 = &ey[0][0];
      const DATA_TYPE fv = _fict_[t];

      for (j = 0; j < _PB_NY; ++j)
        ey0[j] = fv;

      for (i = 1; i < _PB_NX; ++i) {
        DATA_TYPE *restrict eyi   = &ey[i][0];
        DATA_TYPE *restrict hzi   = &hz[i][0];
        DATA_TYPE *restrict hzim1 = &hz[i - 1][0];

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
        for (j = 0; j < _PB_NY; ++j)
          eyi[j] = eyi[j] - c05 * (hzi[j] - hzim1[j]);
      }

      for (i = 0; i < _PB_NX; ++i) {
        DATA_TYPE *restrict exi = &ex[i][0];
        DATA_TYPE *restrict hzi = &hz[i][0];

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
        for (j = 1; j < _PB_NY; ++j)
          exi[j] = exi[j] - c05 * (hzi[j] - hzi[j - 1]);
      }

      for (i = 0; i < _PB_NX - 1; ++i) {
        DATA_TYPE *restrict hzi   = &hz[i][0];
        DATA_TYPE *restrict exi   = &ex[i][0];
        DATA_TYPE *restrict eyi   = &ey[i][0];
        DATA_TYPE *restrict eyip1 = &ey[i + 1][0];

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
        for (j = 0; j < _PB_NY - 1; ++j)
          hzi[j] = hzi[j] - c07 * (exi[j + 1] - exi[j] + eyip1[j] - eyi[j]);
      }
    }
  }

#pragma endscop
}

static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
  {
    DATA_TYPE * __restrict pk = &path[k][0];

    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE * __restrict pi = &path[i][0];
      DATA_TYPE pik = pi[k];

      for (j = 0; j < _PB_N; j++)
      {
        DATA_TYPE alt = pik + pk[j];
        pi[j] = pi[j] < alt ? pi[j] : alt;
      }
    }
  }
#pragma endscop

}

static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *c_row = &C[i][0];
    DATA_TYPE *a_row = &A[i][0];

    for (j = 0; j < _PB_NJ; j++)
      c_row[j] *= beta;

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE prod = alpha * a_row[k];
      DATA_TYPE *b_row = &B[k][0];

      j = 0;

#if defined(__GNUC__) || defined(__clang__)
      {
        int limit = _PB_NJ;

        for (; j + 7 < limit; j += 8) {
          c_row[j + 0] += prod * b_row[j + 0];
          c_row[j + 1] += prod * b_row[j + 1];
          c_row[j + 2] += prod * b_row[j + 2];
          c_row[j + 3] += prod * b_row[j + 3];
          c_row[j + 4] += prod * b_row[j + 4];
          c_row[j + 5] += prod * b_row[j + 5];
          c_row[j + 6] += prod * b_row[j + 6];
          c_row[j + 7] += prod * b_row[j + 7];
        }
        for (; j + 3 < limit; j += 4) {
          c_row[j + 0] += prod * b_row[j + 0];
          c_row[j + 1] += prod * b_row[j + 1];
          c_row[j + 2] += prod * b_row[j + 2];
          c_row[j + 3] += prod * b_row[j + 3];
        }
      }
#endif
      for (; j < _PB_NJ; j++)
        c_row[j] += prod * b_row[j];
    }
  }
#pragma endscop

}

static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = &A[i][0];
    DATA_TYPE u1i = u1[i];
    DATA_TYPE u2i = u2[i];
    for (j = 0; j < _PB_N; j++) {
      Ai[j] = Ai[j] + u1i * v1[j] + u2i * v2[j];
    }
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE xi = x[i];
    for (j = 0; j < _PB_N; j++) {
      xi = xi + beta * A[j][i] * y[j];
    }
    x[i] = xi + z[i];
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = &A[i][0];
    DATA_TYPE wi = w[i];
    for (j = 0; j < _PB_N; j++) {
      wi = wi + alpha * Ai[j] * x[j];
    }
    w[i] = wi;
  }

#pragma endscop
}

static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE * __restrict__ qcol = &Q[0][k];

      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++) {
        DATA_TYPE aik = A[i][k];
        nrm += aik * aik;
      }

      R[k][k] = SQRT_FUN(nrm);

      {
        DATA_TYPE rkk = R[k][k];
        for (i = 0; i < _PB_M; i++)
          qcol[i * n] = A[i][k] / rkk;
      }

      for (j = k + 1; j < _PB_N; j++)
	{
          DATA_TYPE rkj = SCALAR_VAL(0.0);

	  for (i = 0; i < _PB_M; i++)
	    rkj += qcol[i * n] * A[i][j];

          R[k][j] = rkj;

	  for (i = 0; i < _PB_M; i++)
	    A[i][j] = A[i][j] - qcol[i * n] * rkj;
	}
    }
#pragma endscop

}

static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
  {
    const int nn = _PB_N;
    const DATA_TYPE c0 = SCALAR_VAL(0.125);
    const DATA_TYPE c1 = SCALAR_VAL(2.0);

#if defined(__riscv_vector) && defined(__riscv_v_intrinsic) && defined(DATA_TYPE_IS_FLOAT)
    for (t = 1; t <= TSTEPS; t++) {
      for (i = 1; i < nn - 1; i++) {
        for (j = 1; j < nn - 1; j++) {
          DATA_TYPE *restrict a_jm1 = &A[i][j - 1][0];
          DATA_TYPE *restrict a_j   = &A[i][j][0];
          DATA_TYPE *restrict a_jp1 = &A[i][j + 1][0];
          DATA_TYPE *restrict am1_j = &A[i - 1][j][0];
          DATA_TYPE *restrict ap1_j = &A[i + 1][j][0];
          DATA_TYPE *restrict b_j   = &B[i][j][0];

          k = 1;
          while (k < nn - 1) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(nn - 1 - k));

            vfloat32m1_t vc   = __riscv_vle32_v_f32m1(&a_j[k], vl);
            vfloat32m1_t vxp  = __riscv_vle32_v_f32m1(&ap1_j[k], vl);
            vfloat32m1_t vxm  = __riscv_vle32_v_f32m1(&am1_j[k], vl);
            vfloat32m1_t vyp  = __riscv_vle32_v_f32m1(&a_jp1[k], vl);
            vfloat32m1_t vym  = __riscv_vle32_v_f32m1(&a_jm1[k], vl);
            vfloat32m1_t vzp  = __riscv_vle32_v_f32m1(&a_j[k + 1], vl);
            vfloat32m1_t vzm  = __riscv_vle32_v_f32m1(&a_j[k - 1], vl);

            vfloat32m1_t v2c  = __riscv_vfmul_vf_f32m1(vc, c1, vl);

            vfloat32m1_t tx   = __riscv_vfsub_vv_f32m1(vxp, v2c, vl);
            tx                = __riscv_vfadd_vv_f32m1(tx, vxm, vl);

            vfloat32m1_t ty   = __riscv_vfsub_vv_f32m1(vyp, v2c, vl);
            ty                = __riscv_vfadd_vv_f32m1(ty, vym, vl);

            vfloat32m1_t tz   = __riscv_vfsub_vv_f32m1(vzp, v2c, vl);
            tz                = __riscv_vfadd_vv_f32m1(tz, vzm, vl);

            vfloat32m1_t sum  = __riscv_vfadd_vv_f32m1(tx, ty, vl);
            sum               = __riscv_vfadd_vv_f32m1(sum, tz, vl);
            sum               = __riscv_vfmul_vf_f32m1(sum, c0, vl);
            sum               = __riscv_vfadd_vv_f32m1(sum, vc, vl);

            __riscv_vse32_v_f32m1(&b_j[k], sum, vl);
            k += (int)vl;
          }
        }
      }

      for (i = 1; i < nn - 1; i++) {
        for (j = 1; j < nn - 1; j++) {
          DATA_TYPE *restrict b_jm1 = &B[i][j - 1][0];
          DATA_TYPE *restrict b_j   = &B[i][j][0];
          DATA_TYPE *restrict b_jp1 = &B[i][j + 1][0];
          DATA_TYPE *restrict bm1_j = &B[i - 1][j][0];
          DATA_TYPE *restrict bp1_j = &B[i + 1][j][0];
          DATA_TYPE *restrict a_j   = &A[i][j][0];

          k = 1;
          while (k < nn - 1) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(nn - 1 - k));

            vfloat32m1_t vc   = __riscv_vle32_v_f32m1(&b_j[k], vl);
            vfloat32m1_t vxp  = __riscv_vle32_v_f32m1(&bp1_j[k], vl);
            vfloat32m1_t vxm  = __riscv_vle32_v_f32m1(&bm1_j[k], vl);
            vfloat32m1_t vyp  = __riscv_vle32_v_f32m1(&b_jp1[k], vl);
            vfloat32m1_t vym  = __riscv_vle32_v_f32m1(&b_jm1[k], vl);
            vfloat32m1_t vzp  = __riscv_vle32_v_f32m1(&b_j[k + 1], vl);
            vfloat32m1_t vzm  = __riscv_vle32_v_f32m1(&b_j[k - 1], vl);

            vfloat32m1_t v2c  = __riscv_vfmul_vf_f32m1(vc, c1, vl);

            vfloat32m1_t tx   = __riscv_vfsub_vv_f32m1(vxp, v2c, vl);
            tx                = __riscv_vfadd_vv_f32m1(tx, vxm, vl);

            vfloat32m1_t ty   = __riscv_vfsub_vv_f32m1(vyp, v2c, vl);
            ty                = __riscv_vfadd_vv_f32m1(ty, vym, vl);

            vfloat32m1_t tz   = __riscv_vfsub_vv_f32m1(vzp, v2c, vl);
            tz                = __riscv_vfadd_vv_f32m1(tz, vzm, vl);

            vfloat32m1_t sum  = __riscv_vfadd_vv_f32m1(tx, ty, vl);
            sum               = __riscv_vfadd_vv_f32m1(sum, tz, vl);
            sum               = __riscv_vfmul_vf_f32m1(sum, c0, vl);
            sum               = __riscv_vfadd_vv_f32m1(sum, vc, vl);

            __riscv_vse32_v_f32m1(&a_j[k], sum, vl);
            k += (int)vl;
          }
        }
      }
    }
#else
    for (t = 1; t <= TSTEPS; t++) {
      for (i = 1; i < nn - 1; i++) {
        for (j = 1; j < nn - 1; j++) {
          DATA_TYPE *restrict a_jm1 = &A[i][j - 1][0];
          DATA_TYPE *restrict a_j   = &A[i][j][0];
          DATA_TYPE *restrict a_jp1 = &A[i][j + 1][0];
          DATA_TYPE *restrict am1_j = &A[i - 1][j][0];
          DATA_TYPE *restrict ap1_j = &A[i + 1][j][0];
          DATA_TYPE *restrict b_j   = &B[i][j][0];

          for (k = 1; k < nn - 1; k++) {
            DATA_TYPE center = a_j[k];
            b_j[k] = c0 * (ap1_j[k] - c1 * center + am1_j[k])
                   + c0 * (a_jp1[k] - c1 * center + a_jm1[k])
                   + c0 * (a_j[k + 1] - c1 * center + a_j[k - 1])
                   + center;
          }
        }
      }

      for (i = 1; i < nn - 1; i++) {
        for (j = 1; j < nn - 1; j++) {
          DATA_TYPE *restrict b_jm1 = &B[i][j - 1][0];
          DATA_TYPE *restrict b_j   = &B[i][j][0];
          DATA_TYPE *restrict b_jp1 = &B[i][j + 1][0];
          DATA_TYPE *restrict bm1_j = &B[i - 1][j][0];
          DATA_TYPE *restrict bp1_j = &B[i + 1][j][0];
          DATA_TYPE *restrict a_j   = &A[i][j][0];

          for (k = 1; k < nn - 1; k++) {
            DATA_TYPE center = b_j[k];
            a_j[k] = c0 * (bp1_j[k] - c1 * center + bm1_j[k])
                   + c0 * (b_jp1[k] - c1 * center + b_jm1[k])
                   + c0 * (b_j[k + 1] - c1 * center + b_j[k - 1])
                   + center;
          }
        }
      }
    }
#endif
  }
#pragma endscop

}

static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      DATA_TYPE *restrict a = A;
      DATA_TYPE *restrict b = B;
      const DATA_TYPE c = (DATA_TYPE)0.33333;

      for (i = 1; i < _PB_N - 1; i++)
        {
          DATA_TYPE am1 = a[i - 1];
          DATA_TYPE a0  = a[i];
          DATA_TYPE ap1 = a[i + 1];
          b[i] = c * (am1 + a0 + ap1);
        }

      for (i = 1; i < _PB_N - 1; i++)
        {
          DATA_TYPE bm1 = b[i - 1];
          DATA_TYPE b0  = b[i];
          DATA_TYPE bp1 = b[i + 1];
          a[i] = c * (bm1 + b0 + bp1);
        }
    }
#pragma endscop

}

static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      DATA_TYPE *Aj = A[j];
      DATA_TYPE sum = Ai[j];

      for (k = 0; k + 3 < j; k += 4) {
        sum -= Ai[k]     * A[k][j];
        sum -= Ai[k + 1] * A[k + 1][j];
        sum -= Ai[k + 2] * A[k + 2][j];
        sum -= Ai[k + 3] * A[k + 3][j];
      }
      for (; k < j; k++) {
        sum -= Ai[k] * A[k][j];
      }

      Ai[j] = sum / Aj[j];
    }

    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = Ai[j];

      for (k = 0; k + 3 < i; k += 4) {
        sum -= Ai[k]     * A[k][j];
        sum -= Ai[k + 1] * A[k + 1][j];
        sum -= Ai[k + 2] * A[k + 2][j];
        sum -= Ai[k + 3] * A[k + 3][j];
      }
      for (; k < i; k++) {
        sum -= Ai[k] * A[k][j];
      }

      Ai[j] = sum;
    }
  }
#pragma endscop
}

static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      DATA_TYPE sum = 0;
      DATA_TYPE *Akj = &A[0][j];
      for (k = 0; k < j; k++) {
        sum += Ai[k] * (*Akj);
        Akj += n;
      }
      w = Ai[j] - sum;
      Ai[j] = w / A[j][j];
    }

    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = 0;
      DATA_TYPE *Akj = &A[0][j];
      for (k = 0; k < i; k++) {
        sum += Ai[k] * (*Akj);
        Akj += n;
      }
      Ai[j] = Ai[j] - sum;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE sum = 0;
    for (j = 0; j < i; j++)
      sum += Ai[j] * y[j];
    y[i] = b[i] - sum;
  }

  for (i = _PB_N - 1; i >= 0; i--) {
    DATA_TYPE *Ai = A[i];
    DATA_TYPE sum = 0;
    for (j = i + 1; j < _PB_N; j++)
      sum += Ai[j] * x[j];
    x[i] = (y[i] - sum) / Ai[i];
  }
#pragma endscop

}

static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = x1[i];
    DATA_TYPE * __restrict a_row = &A[i][0];
    DATA_TYPE * __restrict y1 = &y_1[0];

    for (j = 0; j + 3 < _PB_N; j += 4) {
      sum += a_row[j] * y1[j]
           + a_row[j + 1] * y1[j + 1]
           + a_row[j + 2] * y1[j + 2]
           + a_row[j + 3] * y1[j + 3];
    }
    for (; j < _PB_N; j++) {
      sum += a_row[j] * y1[j];
    }
    x1[i] = sum;
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = x2[i];
    for (j = 0; j < _PB_N; j++) {
      sum += A[j][i] * y_2[j];
    }
    x2[i] = sum;
  }
#pragma endscop

}

static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = _PB_N - 1; i >= 0; --i) {
    DATA_TYPE *table_i = table[i];
    DATA_TYPE *table_ip1 = (i + 1 < _PB_N) ? table[i + 1] : 0;
    DATA_TYPE seq_i = seq[i];

    for (j = i + 1; j < _PB_N; ++j) {
      DATA_TYPE best = table_i[j];

      best = max_score(best, table_i[j - 1]);
      best = max_score(best, table_ip1[j]);

      {
        DATA_TYPE diag = table_ip1[j - 1];
        if (i < j - 1)
          diag = diag + match(seq_i, seq[j]);
        best = max_score(best, diag);
      }

      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand = table_i[k] + table[k + 1][j];
        best = max_score(best, cand);
      }

      table_i[j] = best;
    }
  }
#pragma endscop

}

static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= _PB_N - 2; i++) {
      DATA_TYPE *rowm1 = &A[i - 1][0];
      DATA_TYPE *row0  = &A[i][0];
      DATA_TYPE *rowp1 = &A[i + 1][0];

      DATA_TYPE left0 = row0[0];

      for (j = 1; j <= _PB_N - 2; j++) {
        DATA_TYPE up_l = rowm1[j - 1];
        DATA_TYPE up_c = rowm1[j];
        DATA_TYPE up_r = rowm1[j + 1];
        DATA_TYPE mid_c = row0[j];
        DATA_TYPE mid_r = row0[j + 1];
        DATA_TYPE dn_l = rowp1[j - 1];
        DATA_TYPE dn_c = rowp1[j];
        DATA_TYPE dn_r = rowp1[j + 1];

        DATA_TYPE sum = up_l + up_c + up_r
                      + left0 + mid_c + mid_r
                      + dn_l + dn_c + dn_r;

        DATA_TYPE newv = sum / SCALAR_VAL(9.0);
        row0[j] = newv;
        left0 = newv;
      }
    }
  }
#pragma endscop

}

static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
#if defined(__riscv_vector) && __has_include(<riscv_vector.h>)
#include <riscv_vector.h>
#endif

#if defined(__riscv_vector) && __has_include(<riscv_vector.h>) && defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE aii = A[i][i];
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE bij = B[i][j];
      DATA_TYPE alpha_bij = alpha * bij;
      temp2 = 0;

      k = 0;
      while (k < i) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(i - k));

        vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][k], vl);
        vfloat64m1_t vb = __riscv_vlse64_v_f64m1(&B[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);

        vfloat64m1_t vc = __riscv_vlse64_v_f64m1(&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, alpha_bij, va, vl);
        __riscv_vsse64_v_f64m1(&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vc, vl);

        {
          vfloat64m1_t prod = __riscv_vfmul_vv_f64m1(vb, va, vl);
          vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
          vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m1_f64m1(prod, vzero, vl);
          temp2 += __riscv_vfmv_f_s_f64m1_f64(vsum);
        }

        k += (int)vl;
      }

      C[i][j] = beta * C[i][j] + alpha_bij * aii + alpha * temp2;
    }
  }
#elif defined(__riscv_vector) && __has_include(<riscv_vector.h>) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE aii = A[i][i];
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE bij = B[i][j];
      DATA_TYPE alpha_bij = alpha * bij;
      temp2 = 0;

      k = 0;
      while (k < i) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(i - k));

        vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][k], vl);
        vfloat32m1_t vb = __riscv_vlse32_v_f32m1(&B[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);

        vfloat32m1_t vc = __riscv_vlse32_v_f32m1(&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
        vc = __riscv_vfmacc_vf_f32m1(vc, alpha_bij, va, vl);
        __riscv_vsse32_v_f32m1(&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vc, vl);

        {
          vfloat32m1_t prod = __riscv_vfmul_vv_f32m1(vb, va, vl);
          vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
          vfloat32m1_t vsum = __riscv_vfredusum_vs_f32m1_f32m1(prod, vzero, vl);
          temp2 += __riscv_vfmv_f_s_f32m1_f32(vsum);
        }

        k += (int)vl;
      }

      C[i][j] = beta * C[i][j] + alpha_bij * aii + alpha * temp2;
    }
  }
#else
   for (i = 0; i < _PB_M; i++)
      for (j = 0; j < _PB_N; j++ )
      {
        DATA_TYPE bij = B[i][j];
        DATA_TYPE alpha_bij = alpha * bij;
        temp2 = 0;
        for (k = 0; k < i; k++) {
           C[k][j] += alpha_bij * A[i][k];
           temp2 += B[k][j] * A[i][k];
        }
        C[i][j] = beta * C[i][j] + alpha_bij * A[i][i] + alpha * temp2;
     }
#endif
#pragma endscop

}

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = C[i];
    DATA_TYPE *Ai = A[i];
    DATA_TYPE *Bi = B[i];

    for (j = 0; j <= i; j++)
      Ci[j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * Ai[k];
      DATA_TYPE bik_alpha = alpha * Bi[k];

      j = 0;

#if defined(__GNUC__) || defined(__clang__)
      for (; j + 3 <= i; j += 4) {
        Ci[j]     += A[j][k]     * bik_alpha + B[j][k]     * aik_alpha;
        Ci[j + 1] += A[j + 1][k] * bik_alpha + B[j + 1][k] * aik_alpha;
        Ci[j + 2] += A[j + 2][k] * bik_alpha + B[j + 2][k] * aik_alpha;
        Ci[j + 3] += A[j + 3][k] * bik_alpha + B[j + 3][k] * aik_alpha;
      }
#endif

      for (; j <= i; j++) {
        Ci[j] += A[j][k] * bik_alpha + B[j][k] * aik_alpha;
      }
    }
  }
#pragma endscop

}

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
#    if defined(DATA_TYPE_IS_DOUBLE)
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = &C[i][0];
    DATA_TYPE *Ai = &A[i][0];

    int rem = i + 1;
    int off = 0;

    while (rem > 0) {
      size_t vl = __riscv_vsetvl_e64m1(rem);
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&Ci[off], vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(&Ci[off], vc, vl);
      off += (int)vl;
      rem -= (int)vl;
    }

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * Ai[k];
      DATA_TYPE *Ak_col = &A[0][k];

      rem = i + 1;
      off = 0;

      while (rem > 0) {
        size_t vl = __riscv_vsetvl_e64m1(rem);
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&Ci[off], vl);
        vfloat64m1_t va = __riscv_vlse64_v_f64m1(&Ak_col[off * m], (ptrdiff_t)(m * sizeof(DATA_TYPE)), vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, aik_alpha, va, vl);
        __riscv_vse64_v_f64m1(&Ci[off], vc, vl);
        off += (int)vl;
        rem -= (int)vl;
      }
    }
  }
#    else
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = &C[i][0];
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j <= i; j++)
      Ci[j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * Ai[k];
      for (j = 0; j <= i; j++)
        Ci[j] += aik_alpha * A[j][k];
    }
  }
#    endif
#  else
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = &C[i][0];
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j <= i; j++)
      Ci[j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * Ai[k];
      for (j = 0; j <= i; j++)
        Ci[j] += aik_alpha * A[j][k];
    }
  }
#  endif
#else
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ci = &C[i][0];
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j <= i; j++)
      Ci[j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * Ai[k];
      for (j = 0; j <= i; j++)
        Ci[j] += aik_alpha * A[j][k];
    }
  }
#endif
#pragma endscop

}

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE sum = b[i];
      DATA_TYPE *Li = &L[i][0];

      j = 0;

#if defined(__GNUC__) || defined(__clang__)
      __builtin_prefetch((const void *)&x[i + 16], 0, 1);
      __builtin_prefetch((const void *)&L[i + 1][0], 0, 1);
#endif

#if defined(__riscv_vector) && defined(__has_include)
# if __has_include(<riscv_vector.h>)
#  include <riscv_vector.h>
#  if defined(DATA_TYPE_IS_FLOAT)
      if (i >= 8)
        {
          size_t vl;
          float acc = 0.0f;
          for (; j < i; j += (int)vl)
            {
              vfloat32m4_t vL, vx, vprod;
              vl = __riscv_vsetvl_e32m4((size_t)(i - j));
              vL = __riscv_vle32_v_f32m4((const float *)&Li[j], vl);
              vx = __riscv_vle32_v_f32m4((const float *)&x[j], vl);
              vprod = __riscv_vfmul_vv_f32m4(vL, vx, vl);
              acc += __riscv_vfmv_f_s_f32m1_f32(
                  __riscv_vfredusum_vs_f32m4_f32m1(
                      vprod,
                      __riscv_vfmv_v_f_f32m1(0.0f, 1),
                      vl));
            }
          sum -= (DATA_TYPE)acc;
        }
#  elif defined(DATA_TYPE_IS_DOUBLE)
      if (i >= 4)
        {
          size_t vl;
          double acc = 0.0;
          for (; j < i; j += (int)vl)
            {
              vfloat64m2_t vL, vx, vprod;
              vl = __riscv_vsetvl_e64m2((size_t)(i - j));
              vL = __riscv_vle64_v_f64m2((const double *)&Li[j], vl);
              vx = __riscv_vle64_v_f64m2((const double *)&x[j], vl);
              vprod = __riscv_vfmul_vv_f64m2(vL, vx, vl);
              acc += __riscv_vfmv_f_s_f64m1_f64(
                  __riscv_vfredusum_vs_f64m2_f64m1(
                      vprod,
                      __riscv_vfmv_v_f_f64m1(0.0, 1),
                      vl));
            }
          sum -= (DATA_TYPE)acc;
        }
#  endif
#endif

      for (; j < i; j++)
        sum -= Li[j] * x[j];

      x[i] = sum / Li[i];
    }
#pragma endscop
}

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
#    if defined(DATA_TYPE_IS_DOUBLE)

  for (i = 0; i < _PB_M; i++) {
    int jx = 0;
    const DATA_TYPE *Ai_col = &A[i + 1][i];

    for (; jx < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e64m2((size_t)(_PB_N - jx));
      vfloat64m2_t acc = __riscv_vle64_v_f64m2(&B[i][jx], vl);

      k = i + 1;
      for (; k + 1 < _PB_M; k += 2) {
        DATA_TYPE a0 = Ai_col[k - (i + 1)];
        DATA_TYPE a1 = Ai_col[k + 1 - (i + 1)];
        vfloat64m2_t b0 = __riscv_vle64_v_f64m2(&B[k][jx], vl);
        vfloat64m2_t b1 = __riscv_vle64_v_f64m2(&B[k + 1][jx], vl);
        acc = __riscv_vfmacc_vf_f64m2(acc, a0, b0, vl);
        acc = __riscv_vfmacc_vf_f64m2(acc, a1, b1, vl);
      }
      for (; k < _PB_M; k++) {
        vfloat64m2_t bk = __riscv_vle64_v_f64m2(&B[k][jx], vl);
        acc = __riscv_vfmacc_vf_f64m2(acc, A[k][i], bk, vl);
      }

      acc = __riscv_vfmul_vf_f64m2(acc, alpha, vl);
      __riscv_vse64_v_f64m2(&B[i][jx], acc, vl);
      jx += (int)vl;
    }
  }

#    elif defined(DATA_TYPE_IS_FLOAT)

  for (i = 0; i < _PB_M; i++) {
    int jx = 0;
    const DATA_TYPE *Ai_col = &A[i + 1][i];

    for (; jx < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e32m4((size_t)(_PB_N - jx));
      vfloat32m4_t acc = __riscv_vle32_v_f32m4(&B[i][jx], vl);

      k = i + 1;
      for (; k + 1 < _PB_M; k += 2) {
        DATA_TYPE a0 = Ai_col[k - (i + 1)];
        DATA_TYPE a1 = Ai_col[k + 1 - (i + 1)];
        vfloat32m4_t b0 = __riscv_vle32_v_f32m4(&B[k][jx], vl);
        vfloat32m4_t b1 = __riscv_vle32_v_f32m4(&B[k + 1][jx], vl);
        acc = __riscv_vfmacc_vf_f32m4(acc, a0, b0, vl);
        acc = __riscv_vfmacc_vf_f32m4(acc, a1, b1, vl);
      }
      for (; k < _PB_M; k++) {
        vfloat32m4_t bk = __riscv_vle32_v_f32m4(&B[k][jx], vl);
        acc = __riscv_vfmacc_vf_f32m4(acc, A[k][i], bk, vl);
      }

      acc = __riscv_vfmul_vf_f32m4(acc, alpha, vl);
      __riscv_vse32_v_f32m4(&B[i][jx], acc, vl);
      jx += (int)vl;
    }
  }

#    else

  for (i = 0; i < _PB_M; i++) {
     for (j = 0; j < _PB_N; j++) {
        DATA_TYPE bij = B[i][j];
        for (k = i+1; k < _PB_M; k++)
           bij += A[k][i] * B[k][j];
        B[i][j] = alpha * bij;
     }
  }

#    endif
#  else

  for (i = 0; i < _PB_M; i++) {
     for (j = 0; j < _PB_N; j++) {
        DATA_TYPE bij = B[i][j];
        for (k = i+1; k < _PB_M; k++)
           bij += A[k][i] * B[k][j];
        B[i][j] = alpha * bij;
     }
  }

#  endif
#else

  for (i = 0; i < _PB_M; i++) {
     for (j = 0; j < _PB_N; j++) {
        DATA_TYPE bij = B[i][j];
        for (k = i+1; k < _PB_M; k++)
           bij += A[k][i] * B[k][j];
        B[i][j] = alpha * bij;
     }
  }

#endif
#pragma endscop

}
